<?php
require __DIR__.'/../app/bootstrap.php';$u=require_admin();$title='Platform overview';
$metrics=[['Customers',(int)q("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn()],['Approved sellers',(int)q("SELECT COUNT(*) FROM seller_applications WHERE status='approved'")->fetchColumn()],['Pending applications',(int)q("SELECT COUNT(*) FROM seller_applications WHERE status='pending'")->fetchColumn()],['Active categories',(int)q('SELECT COUNT(*) FROM categories WHERE active=1')->fetchColumn()]];
$pending=all("SELECT s.*,u.full_name FROM seller_applications s JOIN users u ON u.id=s.user_id WHERE s.status='pending' ORDER BY s.submitted_at LIMIT 5");$cats=all('SELECT c.name,COUNT(m.id) n FROM categories c LEFT JOIN menu_items m ON m.category_id=c.id GROUP BY c.id,c.name ORDER BY n DESC');$peak=max(1,...array_column($cats,'n'));require ROOT.'/app/workspace-start.php'; ?>
<div class="dash-header"><div><span class="heading-kicker">ADMIN CONTROL</span><h1>Platform overview</h1><p class="dash-sub">The big picture of your food community.</p></div><a class="pill primary" href="<?=e(url('admin/applications.php'))?>">Review applications →</a></div><div class="metrics"><?php foreach($metrics as [$label,$count]): ?><div class="metric"><div class="metric-icon">✦</div><div class="metric-label"><?=e($label)?></div><div class="metric-value"><?=$count?></div></div><?php endforeach ?></div><div class="dash-grid"><section class="panel"><div class="panel-top"><h2>Dishes by category</h2><small>All menu records</small></div><?php foreach($cats as $c): ?><div class="horizontal-metric"><span><?=e($c['name'])?></span><div class="track"><div style="width:<?=round($c['n']/$peak*100)?>%"></div></div><b><?=$c['n']?></b></div><?php endforeach ?><?php if(!$cats): ?><p class="empty">Add categories to organize your marketplace.</p><?php endif ?></section><section class="panel lavender"><span class="heading-kicker">BUILD YOUR MARKETPLACE</span><h2>A place for every flavor.</h2><p>You decide which categories appear to customers and sellers.</p><a class="pill" href="<?=e(url('admin/categories.php'))?>">Manage categories →</a></section></div><section class="panel list-panel"><div class="panel-top"><h2>Waiting for your review</h2><a href="<?=e(url('admin/applications.php'))?>">View all →</a></div><?php if(!$pending): ?><p class="empty">You’re all caught up. No pending applications.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Business</th><th>Owner</th><th>Submitted</th><th>Action</th></tr></thead><tbody><?php foreach($pending as $a): ?><tr><td><?=e($a['business_name'])?></td><td><?=e($a['full_name'])?></td><td><?=e(local_time($a['submitted_at']))?></td><td><a class="pill compact" href="<?=e(url('admin/application.php?id='.$a['id']))?>">Review</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
